// "Where in the world?": pick the part of the world whose animals you hear, on the map or from the
// list under it. Fetched the first time someone opens it (components/areapick.js).
import { AREAS, areaSize } from "../areas.js";
import { MAP } from "../data/world-map.js";
import { store } from "../store.js";
import { sfx } from "../sfx.js";
import { openModal } from "./modals.js";
import { $, $$, esc } from "../util.js";

export function showAreaPicker() {
  const land = Object.entries(MAP.paths)
    .map(([key, d]) => `<path d="${d}" data-land="${key}"><title>${esc(AREAS.find((a) => a.key === key).name)}</title></path>`)
    .join("");
  openModal(
    "Where in the world?",
    `<p class="area-intro">Each part of the world has its own animal every day, the same for everyone who picks it.</p>
    <div class="area-map"><svg viewBox="0 0 ${MAP.width} ${MAP.height}" aria-hidden="true">${land}</svg></div>
    <div class="area-list" role="group" aria-label="Parts of the world">${AREAS.map(
      (a) => `<button type="button" class="area-opt" data-area="${a.key}" aria-pressed="${a.key === store.area}">
        <span class="ao-text"><b>${esc(a.name)}</b><small>${esc(a.blurb)}</small></span><span class="ao-count">${areaSize(a.key)}<small>animals</small></span></button>`,
    ).join("")}</div>
    <p class="area-foot">Pets and farm animals live everywhere, so they can turn up in any part. Your streak counts wherever you listen, and each part keeps its own past days.</p>`,
    {
      cls: "area-modal",
      onMount: (root, close) => {
        const map = $(".area-map", root);
        const paint = (hover) => {
          const on = store.area;
          $$("[data-land]", map).forEach((p) => {
            p.classList.toggle("on", on === "world" || p.dataset.land === on);
            p.classList.toggle("hover", hover === "world" || p.dataset.land === hover);
          });
          $$(".area-opt", root).forEach((b) => b.classList.toggle("hover", b.dataset.area === hover));
        };
        const choose = (key) => {
          sfx.tap();
          const changed = key !== store.area;
          store.area = key;
          close();
          // The page underneath redraws for the new part of the world (app.js).
          if (changed) window.dispatchEvent(new CustomEvent("duskhunt:area"));
        };
        $$(".area-opt", root).forEach((b) => {
          b.addEventListener("click", () => choose(b.dataset.area));
          b.addEventListener("pointerenter", () => paint(b.dataset.area));
          b.addEventListener("focus", () => paint(b.dataset.area));
        });
        $(".area-list", root).addEventListener("pointerleave", () => paint(null));
        $(".area-list", root).addEventListener("focusout", (e) => !e.relatedTarget?.closest(".area-opt") && paint(null));
        // The map works like the list: tap a continent to pick it.
        map.addEventListener("click", (e) => {
          const land = e.target.closest("[data-land]");
          if (land) choose(land.dataset.land);
        });
        map.addEventListener("pointerover", (e) => paint(e.target.closest("[data-land]")?.dataset.land || null));
        map.addEventListener("pointerleave", () => paint(null));
        paint(null);
        // Keyboard users start on the part they're in now.
        if (!matchMedia("(pointer: coarse)").matches) $('.area-opt[aria-pressed="true"]', root)?.focus();
      },
    },
  );
}
